const briefData = $('4. Parse Production Brief').item.json;
let sourcesText = '';
try {
  const response = $input.item.json;
  let raw = response.choices[0].message.content || '';
  raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  const sources = JSON.parse(raw);
  if (Array.isArray(sources) && sources.length > 0) {
    sourcesText = sources.map((s, i) => {
      let line = `${i+1}. ${s.screenshot || ''}\n`;
      line += `   Source: ${s.source_name || ''}\n`;
      if (s.source_url) line += `   URL: ${s.source_url}\n`;
      if (s.search_query) line += `   Search: ${s.search_query}`;
      return line;
    }).join('\n\n');
  }
} catch(e) {
  sourcesText = 'Could not resolve screenshot sources.';
}
return { json: { ...briefData, screenshot_sources: sourcesText } };

