const response = $input.item.json;
const sourceData = $('2. Extract Record Data').item.json;
const cfg = sourceData.cfg || {};
const pb = cfg.production_brief || {};
let raw = '';
try { raw = response.choices[0].message.content || ''; } catch(e) { raw = ''; }
raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();
let brief = {};
try { brief = JSON.parse(raw); } catch(e) { brief = { parse_error: 'Failed: ' + raw.substring(0, 200) }; }

const cueOf = (x) => x.cue || x.cue_point || x.timestamp || x.time || x.start || '';
const cueEndOf = (x) => x.cue_end || x.end || x.timestamp_end || '';
const noteOf = (x) => x.reason || x.description_note || x.note || x.purpose || '';

const fmtCued = (arr, labelKeys) => {
  if (!Array.isArray(arr)) return String(arr || '');
  return arr.map((x, i) => {
    if (typeof x === 'string') return `${i+1}. ${x}`;
    if (typeof x === 'object' && x !== null) {
      let label = '';
      for (const k of labelKeys) { if (x[k]) { label = x[k]; break; } }
      if (!label) { label = Object.entries(x).filter(([k]) => ['cue','cue_point','timestamp','time','start','cue_end','end','timestamp_end','reason','note','purpose'].indexOf(k) === -1).map(([k,v]) => `${k}: ${v}`).join(' | '); }
      const c = cueOf(x);
      const ce = cueEndOf(x);
      let range = '';
      if (c && ce) range = ` at ${c}-${ce}`;
      else if (c) range = ` at ${c}`;
      const note = noteOf(x);
      let line = `${label}${range}`;
      if (note) line += ` \u2014 ${note}`;
      return `${i+1}. ${line}`;
    }
    return `${i+1}. ${x}`;
  }).join('\n');
};

const fmtMusic = (arr) => {
  if (!Array.isArray(arr)) return String(arr || '');
  return arr.map((x, i) => {
    if (typeof x === 'string') return `${i+1}. ${x}`;
    if (typeof x === 'object' && x !== null) {
      const variant = x.variant || x.name || x.title || '';
      const part = x.part ? ` (${x.part})` : '';
      const c = cueOf(x);
      const at = c ? ` starts at ${c}` : '';
      const prompt = x.prompt || '';
      return `${i+1}. ${variant}${part}${at}\n${prompt}`;
    }
    return `${i+1}. ${String(x)}`;
  }).join('\n\n');
};

const fmtSfx = (arr) => {
  if (!Array.isArray(arr)) return String(arr || '');
  return arr.map((x, i) => {
    if (typeof x === 'string') return `${i+1}. ${x}`;
    if (typeof x === 'object' && x !== null) {
      const n = x.sound || x.name || x.effect || '';
      const c = cueOf(x);
      const dsc = noteOf(x);
      let l = n;
      if (c) l += ` at ${c}`;
      if (dsc) l += ` \u2014 ${dsc}`;
      return `${i+1}. ${l || JSON.stringify(x)}`;
    }
    return `${i+1}. ${x}`;
  }).join('\n');
};

const ct = brief.cutting_technique || {};
const ctLine = (label, v) => {
  if (typeof v === 'string') return `${label}: ${v}`;
  if (v && typeof v === 'object') {
    const c = cueOf(v);
    const t = v.technique || v.description || v.note || '';
    return `${label}${c ? ` at ${c}` : ''}: ${t}`;
  }
  return `${label}: `;
};
const cuttingText = [
  ctLine('Hook \u2192 Main', ct.hook_to_main),
  ctLine('Main \u2192 Pain', ct.main_to_pain),
  ctLine('Pain \u2192 Solution', ct.pain_to_solution),
  ctLine('Solution \u2192 CTA', ct.solution_to_cta)
].join('\n');

return { json: {
  cfg: cfg,
  record_id: sourceData.record_id,
  heygen_video_id: sourceData.heygen_video_id,
  screenshots_needed: fmtCued(brief.screenshots_needed, ['screenshot','description','item']),
  screenshots_needed_raw: sourceData.screenshots_needed || '',
  broll_generated: fmtCued(brief.broll_generated, ['description','broll','footage','item']),
  broll_reference: fmtCued(brief.broll_reference, ['query','search_query','reference','item']),
  hook_video_brief: brief.hook_video_brief || '',
  sound_effects: fmtSfx(brief.sound_effects),
  music_bgm: fmtMusic(brief.music_bgm),
  cutting_technique: cuttingText,
  soundbite: brief.soundbite || pb.soundbite_default || 'agent done for you by Alfred Ai',
  content_type: sourceData.content_type,
  platform: sourceData.platform
} };

const d = $input.item.json;
const cfg = d.cfg || {};
const pb = cfg.production_brief || {};

const WPM = pb.wpm || 150;
const SFX = pb.sfx_vocabulary || 'digital_readout, whoosh, impact, riser, ding, air_hit, keyboard, mouse_click, double_click, notification, camera_shutter, digital_shutter';
const SOUNDBITE = pb.soundbite_default || 'agent done for you by Alfred Ai';
const SONIC_DNA = pb.sonic_dna || 'LOCKED SONIC DNA across both parts: key of A minor; warm and dark authoritative tone, never bright or harsh; warm spectral character focused in the 1500-2000 Hz range; deep, present, grounding bass; smooth warm synth melody over rich sustained atmospheric pads; punchy four-on-the-floor kick drum with crisp hi-hats; subtle industrial/construction textures (distant metallic clinks, rhythmic mechanical pulses) blended smoothly into the beat, never overpowering; spacious midrange left clear for voiceover narration; clean professional studio mix with no distortion. TEMPO STRUCTURE: Part 1 sits at 120 BPM. Part 2 begins with a smooth intentional 2-3 second tempo ramp from 120 to 140 BPM at the transition point, then holds 140 BPM. Part 1 must build gradually toward the transition. Part 2 must build to a powerful climax near the end, then fade out gradually and smoothly over the final 1-2 seconds. Part 1 intensity rules - News: moderate intensity, establish the hook, build anticipation. Education: intellectual understated pulse, warm pads lead, clarifying feel. Product: sparse minimal arrangement, deep gentle bass, subtle UI textures, effortless automation feel. Part 2 intensity rules - News: high intensity, punchier drum transients, pronounced construction/metallic textures, forward-leaning urgent action-oriented momentum. Education: deeper grounded feel, more resonant pads, construction-industry-specific sonic texture. Product: energetic tech-forward, prominent celebratory lead synth, rhythmic integrated mechanical textures. Every prompt must begin with "Instrumental only, no vocals." and end with "Keep the tone warm and dark, not bright or harsh; keep the bass deep and present, not thin; no electric guitars, no acoustic drums, no orchestral strings or horns, no chaotic or erratic tempo changes; drums punchy but never overwhelming the voiceover."';

const P = [];
P.push('You are creating a production brief for a ' + d.content_type + ' video for ' + d.platform + '.');
P.push('');
P.push('TOPIC: ' + d.topic);
P.push('CATEGORY: ' + d.category);
P.push('');
P.push('FINAL SCRIPT:');
P.push(d.script);
P.push('');
P.push('TIMING RULES (mandatory - every cue must be computed from the script, never guessed):');
P.push('- Assume the voiceover is read at ' + WPM + ' words per minute.');
P.push('- To time any sentence: count the words that appear before it in the script, then cue = round(words_before / ' + WPM + ' * 60) seconds, formatted m:ss.');
P.push('- Total script duration = round(total_words / ' + WPM + ' * 60) seconds. No cue may exceed it.');
P.push('- Format every timestamp as m:ss, e.g. 0:07 or 1:24. Never seconds-only, never a range inside a single cue field.');
P.push('- Within each list, cues must ascend and must not repeat.');
P.push('- Every cue must land on the moment in the script the item actually supports. Anchor it to a specific sentence.');
P.push('');
P.push('Generate a complete production brief as a JSON object with these exact keys:');
P.push('');
P.push('{');
P.push('  "screenshots_needed": [list of objects, each with "screenshot" (specific description of the screenshot), "cue" (m:ss where it appears on screen), "reason" (one sentence on what point in the script it supports)],');
P.push('  "broll_generated": [list of 3-5 objects, each with "description" (the b-roll footage to source or generate), "cue" (m:ss where the clip starts), "cue_end" (m:ss where the clip ends), "reason" (one sentence on the script moment it covers)],');
P.push('  "broll_reference": [list of 3-5 objects, each with "query" (a stock-footage search query for matching visual style), "cue" (m:ss), "cue_end" (m:ss). Index-align these to broll_generated: entry N here must reference the same moment as entry N there, with the same cue and cue_end],');
P.push('  "hook_video_brief": "4-second opening hook direction, covering 0:00 to 0:04",');
P.push('  "sound_effects": [list of objects - each must use "sound" (must be exactly one of: ' + SFX + '), "cue" (m:ss), and "reason" (one sentence on why this sound fits this moment)],');
P.push('  "music_bgm": [Two objects - one for Part 1 (opening, 0-40% of video) and one for Part 2 (transition, 40-100% of video). Each object must have exactly these keys: "variant": MUST be set using the CATEGORY field provided above. Format exactly as "[CATEGORY] - Part 1 (120 BPM)" for Part 1 and "[CATEGORY] - Part 2 (140 BPM)" for Part 2. Do NOT infer the category from the script content. Use only the CATEGORY value supplied. "part": either "Part 1" or "Part 2". "cue": m:ss where that part starts - Part 1 is always 0:00, Part 2 starts at 40 percent of total script duration. "prompt": a complete ready-to-use music generation prompt following AlfredAI sonic DNA. ' + SONIC_DNA + '],');
P.push('  "cutting_technique": {"hook_to_main": {"cue": "m:ss", "technique": ""}, "main_to_pain": {"cue": "m:ss", "technique": ""}, "pain_to_solution": {"cue": "m:ss", "technique": ""}, "solution_to_cta": {"cue": "m:ss", "technique": ""}},');
P.push('  "soundbite": "' + SOUNDBITE + '"');
P.push('}');
P.push('');
P.push('Be specific, practical and editor-ready. Return ONLY the JSON object - no markdown, no explanation, no code fences.');

let userPrompt = P.join('\n');

// A full template in cfg.production_brief.user_prompt_template overrides the built-in prompt.
if (pb.user_prompt_template) {
  const vars = { topic: d.topic, category: d.category, script: d.script, content_type: d.content_type, platform: d.platform, brand: cfg.brand_name || cfg.client_name || '', wpm: String(WPM), sfx_vocabulary: SFX, sonic_dna: SONIC_DNA, soundbite: SOUNDBITE };
  userPrompt = String(pb.user_prompt_template).replace(/\{\{\s*([A-Za-z_]+)\s*\}\}/g, (m, k) => {
    const key = k.toLowerCase();
    return Object.prototype.hasOwnProperty.call(vars, key) ? String(vars[key]) : m;
  });
}

const body = {
  model: pb.model || 'gpt-4.1-mini',
  messages: [
    { role: 'system', content: pb.system_prompt || 'You are a professional video editor and content strategist for AlfredAI. You produce precise, actionable production briefs for video editors. Every asset you list must carry a timestamp cue computed from the script at ' + WPM + ' words per minute, so the editor knows exactly where it belongs on the timeline. Always respond with valid JSON only - no markdown, no explanation, no code fences.' },
    { role: 'user', content: userPrompt }
  ],
  temperature: (pb.temperature !== undefined && pb.temperature !== null) ? pb.temperature : 0.6,
  max_tokens: pb.max_tokens || 3000
};
return { json: { ...d, brief_body: JSON.stringify(body) } };

const brief = $('4. Parse Production Brief').item.json;
const cfg = brief.cfg || {};
const pb = cfg.production_brief || {};
const fetched = $input.item.json || {};
const f = fetched.fields || fetched;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';

const sep = pb.notes_separator || '==============================';
const STAGE_TAG = pb.stage_tag || cfg.notes_stage_tag || 'PRODUCTION BRIEF (WF06c)';
const WPM = pb.wpm || 150;
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = new RegExp('\\n*' + esc(sep) + '\\n' + esc(STAGE_TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const notesBase = freshNotes.replace(blockRe, '').trim();

let triggered = '';
let runtime = 'unknown';
try {
  const raw = $('1z. Attach Config').first().json.started_at || '';
  triggered = raw ? raw.substring(0, 16).replace('T', ' ') : '';
  const s = Date.parse(raw);
  if (s) { const secs = Math.max(0, Math.round((Date.now() - s) / 1000)); runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's'; }
} catch (e) {}

const countItems = (s) => { if (!s) return 0; const m = String(s).match(/^\d+\.\s/gm); return m ? m.length : 0; };
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');

const block = sep + '\n' + STAGE_TAG
  + '\nTriggered: ' + triggered
  + '\nUpdated: ' + stamp
  + '\nRun time: ' + runtime
  + '\nStage: Complete'
  + '\nTiming basis: ' + WPM + ' wpm, cues computed from script'
  + '\nScreenshots: ' + countItems(brief.screenshots_needed)
  + '\nB-roll clips: ' + countItems(brief.broll_generated)
  + '\nB-roll references: ' + countItems(brief.broll_reference)
  + '\nSound effects: ' + countItems(brief.sound_effects)
  + '\nBGM parts: ' + countItems(brief.music_bgm);

const notesFinal = (notesBase ? notesBase + '\n\n' : '') + block;
return { json: { ...brief, sep: sep, stage_tag: STAGE_TAG, notes_base: notesBase, reel_notes_final: notesFinal } };

const OUTPUT_TYPE = 'production_brief';

function parseJson(raw, label) {
  if (!raw) return {};
  try {
    const v = JSON.parse(raw);
    if (v && typeof v === 'object' && !Array.isArray(v)) return v;
    return {};
  } catch (e) { console.log('[0b] Invalid Config_JSON on ' + label + ': ' + e.message); return {}; }
}

const outputs = $input.all().map(i => i.json);
const clients = $('0a. Load Clients').all().map(i => i.json);
const outByKey = {};
for (const o of outputs) {
  const key = (o['Key'] || '').trim().toLowerCase();
  if (key) outByKey[key] = o;
}

const out = [];
for (const c of clients) {
  const name = c['Client_Name'];
  if (!name) continue;
  if (c['Video_Enabled'] !== true) continue;
  if (!c['Video_Base_ID']) continue;
  const o = outByKey[(name + '::' + OUTPUT_TYPE).toLowerCase()] || null;
  const merged = { ...parseJson(c['Config_JSON'], name), ...parseJson(o ? o['Config_JSON'] : '', name + '::' + OUTPUT_TYPE) };
  out.push({ json: { ...merged, client_name: name, video_base_id: c['Video_Base_ID'], brand_name: c['Brand_Name'] || name, notes_stage_tag: c['Notes_Stage_Tag'] || '', output_type: OUTPUT_TYPE } });
}
console.log('[0b] Clients to process: ' + out.length);
return out;

const loop = $('0c. Client Loop');
let cfg = null;
try { cfg = loop.item.json; } catch (e) { cfg = null; }
if (!cfg || !cfg.video_base_id) { throw new Error('Could not resolve client config for this iteration.'); }
return { json: { ...$input.item.json, cfg, started_at: new Date().toISOString() } };

// T-44: continue only when Production_Approval is ticked AND Script_Approval = Approved.
// If any record in this pass is not approved, only those are passed on (to be reverted);
// approved records then run on the next tick, so the client loop is reached once per pass.
const items = $input.all();
const isOk = (j) => {
  const sa = j.Script_Approval;
  const v = (sa && typeof sa === 'object') ? sa.name : sa;
  return j.Production_Approval === true && v === 'Approved';
};
const refused = items.filter(i => !isOk(i.json));
const pick = refused.length ? refused : items;
return pick.map(i => ({ json: { ...i.json, _approved: refused.length === 0 } }));

const rec = $input.item.json || {};
const f = rec.fields || rec;
const cfg = $('1z. Attach Config').first().json.cfg || {};
const pb = cfg.production_brief || {};
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';

const sep = pb.notes_separator || '==============================';
const STAGE_TAG = pb.stage_tag || cfg.notes_stage_tag || 'PRODUCTION BRIEF (WF06c)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = new RegExp('\\n*' + esc(sep) + '\\n' + esc(STAGE_TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const notesBase = freshNotes.replace(blockRe, '').trim();
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');

const block = sep + '\n' + STAGE_TAG
  + '\nUpdated: ' + stamp
  + '\nStage: Skipped'
  + '\nNot approved: skipped';

return { json: { record_id: rec.id || '', revert_status: 'Video Ready', reel_notes_final: (notesBase ? notesBase + '\n\n' : '') + block } };
